/* =========================================================
   TYPES INFÉRÉS
========================================================= */

type TranslationNamespace = keyof typeof translations
type TranslationKeys<NS extends TranslationNamespace> = keyof typeof translations[NS]['fr']

/* =========================================================
   HOOK useT
   ─────────────────────────────────────────────────────────
   Usage :
     const t = useT('popup')
     t('domains')          // → "Domaines" ou "Domains"
     t('limitDomains', 3)  // si c'est une fonction avec arg
========================================================= */

let _cachedLocale: Locale | null = null

export function getLocale(): Locale {
    if (!_cachedLocale) {
        _cachedLocale = detectLocale()
    }
    return _cachedLocale
}

type TranslationValue = string | ((...args: any[]) => string)

export function useT<NS extends TranslationNamespace>(namespace: NS) {
    const locale = getLocale()
    const dict = translations[namespace][locale] as Record<string, TranslationValue>
    const fallback = translations[namespace]['en'] as Record<string, TranslationValue>

    return function t(
        key: TranslationKeys<NS>,
        ...args: any[]
    ): string {
        const k = key as string
        const val = dict[k] ?? fallback[k]
        if (!val) return k
        if (typeof val === 'function') return val(...args)
        return val
    }
}

/* Version sans hook (pour les fichiers non-React comme blocked/App.tsx) */
export function getT<NS extends TranslationNamespace>(namespace: NS) {
    return useT(namespace)
}